function cnScore(x) {
  var h = String(x || '').substring(0, 4000);
  var good = (h.match(/[的是一了不我他她们这那有和就都而在中为上到下个]/g) || []).length;
  var bad = (h.match(/[\uFFFD锟]/g) || []).length;
  return good * 3 - bad * 12;
}
var u = String(baseUrl || '').replace(/,{[\s\S]*$/, '');
var s = String(result || '');
var sc = cnScore(s);
if (sc < 200) {
  var hex = '';
  try { hex = String(java.ajax(u + ',{"type":"hex"}')); } catch (e) { hex = ''; }
  if (hex && hex.length > 20) {
    var bytes = null;
    try { bytes = java.hexDecodeToByteArray(hex); } catch (e) { bytes = null; }
    if (bytes) {
      var cands = ['utf-8', 'gb18030'];
      for (var i = 0; i < cands.length; i++) {
        try {
          var t = String(java.bytesToStr(bytes, cands[i]));
          var s2 = cnScore(t);
          if (s2 > sc) { s = t; sc = s2; }
        } catch (e) { }
      }
    }
  }
}
s = s.replace(/\r/g, '').replace(/[\u3000 ]+/g, '').replace(/\n{3,}/g, '\n\n');
var out = s.trim();
